import React, { useState } from 'react';
import SimpleEditor from './SimpleEditor';

function MiniThoughtCard({ thought, book, thoughtTypes, onDetach }) {
  const typeInfo = (thoughtTypes || []).find(t => t.id === thought.type) || { color: '#7a6a52', bg: '#f0e8d8', label: thought.type };
  return (
    <div style={{ background: 'var(--paper-card)', border: '1px solid var(--paper-3)', borderLeft: `3px solid ${typeInfo.color}`, borderRadius: 8, padding: '10px 12px', marginBottom: 8 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 6, flexWrap: 'wrap' }}>
        <div style={{ width: 6, height: 6, borderRadius: '50%', background: book?.color || '#888' }} />
        <span style={{ fontSize: 11, color: 'var(--ink-3)', fontStyle: 'italic' }}>{book?.title}</span>
        <span style={{ fontSize: 10, padding: '1px 7px', borderRadius: 20, background: typeInfo.bg + '44', color: typeInfo.color, fontFamily: 'var(--font-mono)' }}>{typeInfo.label}</span>
        {thought.page && <span style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)' }}>p.{thought.page}</span>}
        <button onClick={() => onDetach(thought.id)} style={{ marginLeft: 'auto', fontSize: 11, color: 'var(--ink-4)', padding: '0 2px', cursor: 'pointer' }}>✕</button>
      </div>
      {thought.quote && <p style={{ fontSize: 12, color: 'var(--ink-3)', fontStyle: 'italic', lineHeight: 1.6, borderLeft: '2px solid var(--paper-3)', paddingLeft: 8, marginBottom: 6 }}>"{thought.quote}"</p>}
      <p style={{ fontSize: 13, color: 'var(--ink)', lineHeight: 1.6 }}>{thought.text}</p>
      {thought.topics?.length > 0 && (
        <div style={{ marginTop: 7, display: 'flex', gap: 4, flexWrap: 'wrap' }}>
          {thought.topics.map(tp => <span key={tp} style={{ fontSize: 10, padding: '1px 8px', borderRadius: 20, background: 'var(--paper-2)', color: 'var(--ink-3)', fontFamily: 'var(--font-mono)' }}>#{tp}</span>)}
        </div>
      )}
    </div>
  );
}

function CopyBtn({ text, label = 'Copy' }) {
  const [copied, setCopied] = useState(false);
  return (
    <button onClick={() => { navigator.clipboard?.writeText(text); setCopied(true); setTimeout(() => setCopied(false), 1500); }}
      style={{ fontSize: 11, padding: '4px 12px', borderRadius: 6, border: '1px solid var(--paper-3)', color: copied ? 'var(--green)' : 'var(--ink-3)', background: 'var(--paper-2)', cursor: 'pointer' }}>
      {copied ? '✓ Copied' : label}
    </button>
  );
}

export default function TopicPage({ topic, thoughts, books, allThoughts, thoughtTypes, onUpdate, onDelete, onBack, onCreateSubTopic }) {
  const [editingTitle, setEditingTitle] = useState(false);
  const [titleDraft, setTitleDraft] = useState(topic.title);
  const [showAttachPicker, setShowAttachPicker] = useState(false);
  const [attachSearch, setAttachSearch] = useState('');

  const attachedThoughts = thoughts;
  const bookIds = [...new Set(attachedThoughts.map(t => t.bookId))];
  const byBook = bookIds.map(bid => ({ book: books.find(b => b.id === bid), thoughts: attachedThoughts.filter(t => t.bookId === bid) }));

  const unattached = allThoughts.filter(t =>
    !topic.thoughtIds.includes(t.id) &&
    (attachSearch === '' || t.text?.toLowerCase().includes(attachSearch.toLowerCase()) || t.topics?.some(tp => tp.includes(attachSearch.toLowerCase())))
  );

  const handleTitleSave = () => { setEditingTitle(false); if (titleDraft.trim()) onUpdate({ ...topic, title: titleDraft.trim() }); };
  const handleSummaryChange = (val) => onUpdate({ ...topic, summary: val });
  const handleEssayChange   = (val) => onUpdate({ ...topic, essay: val });
  const handleDetach = (thoughtId) => onUpdate({ ...topic, thoughtIds: topic.thoughtIds.filter(id => id !== thoughtId) });
  const handleAttach = (thoughtId) => { onUpdate({ ...topic, thoughtIds: [...topic.thoughtIds, thoughtId] }); setAttachSearch(''); };

  const lastUpdated = new Date(topic.updatedAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

  // Build a plain-text export of everything on this page
  const buildExportText = () => {
    const lines = [`# ${topic.title}`, ''];
    if (topic.summary) { lines.push('## Summary', topic.summary, ''); }
    if (topic.essay) {
      const plain = topic.essay.replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').trim();
      if (plain) { lines.push('## Essay', plain, ''); }
    }
    if (attachedThoughts.length) {
      lines.push('## Notes from books', '');
      byBook.forEach(({ book, thoughts: bThoughts }) => {
        lines.push(`### ${book?.title || 'Unknown'}`);
        bThoughts.forEach(t => {
          if (t.quote) lines.push(`> "${t.quote}"`);
          lines.push(t.text);
          lines.push('');
        });
      });
    }
    return lines.join('\n');
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      {/* Header */}
      <div style={{ padding: '12px 22px 10px', borderBottom: '1px solid var(--paper-3)', display: 'flex', alignItems: 'center', gap: 10, flexShrink: 0 }}>
        <button onClick={onBack} style={{ fontSize: 13, color: 'var(--ink-3)', cursor: 'pointer', padding: '4px 0', display: 'flex', alignItems: 'center', gap: 4, background: 'none', border: 'none' }}>← Topics</button>
        <div style={{ width: 1, height: 16, background: 'var(--paper-3)' }} />
        {editingTitle ? (
          <input autoFocus value={titleDraft} onChange={e => setTitleDraft(e.target.value)} onBlur={handleTitleSave} onKeyDown={e => e.key === 'Enter' && handleTitleSave()}
            style={{ fontSize: 15, fontWeight: 500, border: 'none', background: 'transparent', outline: 'none', flex: 1, color: 'var(--ink)' }} />
        ) : (
          <h1 onClick={() => setEditingTitle(true)} style={{ fontSize: 15, fontWeight: 500, cursor: 'text', flex: 1, color: 'var(--ink)' }} title="Click to rename">{topic.title}</h1>
        )}
        {topic.parentId && <span style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', background: 'var(--paper-3)', padding: '2px 7px', borderRadius: 10 }}>sub-topic</span>}
        <span style={{ fontSize: 11, color: 'var(--ink-4)', fontStyle: 'italic', flexShrink: 0 }}>updated {lastUpdated}</span>
        <div style={{ display: 'flex', gap: 6 }}>
          <CopyBtn text={buildExportText()} label="Copy all" />
          {onCreateSubTopic && !topic.parentId && (
            <button onClick={() => onCreateSubTopic(topic.id)}
              style={{ fontSize: 12, padding: '5px 12px', borderRadius: 6, border: '1px solid var(--paper-3)', color: 'var(--ink-2)', background: 'var(--paper-2)', cursor: 'pointer' }}>
              + Sub-topic
            </button>
          )}
          <button onClick={() => { if (window.confirm('Delete this topic page?')) onDelete(topic.id); }}
            style={{ fontSize: 11, color: 'var(--ink-4)', padding: '4px 8px', border: '1px solid var(--paper-3)', borderRadius: 6, cursor: 'pointer', background: 'transparent' }}>
            Delete
          </button>
        </div>
      </div>

      {/* Body - two columns */}
      <div style={{ flex: 1, overflow: 'hidden', display: 'grid', gridTemplateColumns: '1fr 1fr' }}>

        {/* LEFT — synthesis */}
        <div style={{ overflow: 'auto', borderRight: '1px solid var(--paper-3)', padding: '18px 22px' }}>
          <div style={SL}>Your synthesis</div>

          <div style={{ marginBottom: 14 }}>
            <div style={{ fontSize: 10, color: 'var(--ink-4)', marginBottom: 6, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>ONE-LINE THESIS</div>
            <div style={{ display: 'flex', gap: 8, alignItems: 'flex-start' }}>
              <textarea value={topic.summary || ''} onChange={e => handleSummaryChange(e.target.value)}
                placeholder="The core idea this topic is circling…" rows={2}
                style={{ flex: 1, resize: 'vertical', padding: '7px 10px', fontSize: 13, lineHeight: 1.6, fontStyle: 'italic', color: 'var(--ink-2)', border: '1px solid var(--paper-3)', borderRadius: 7, background: 'var(--paper-2)', fontFamily: 'var(--font-serif)' }} />
              {topic.summary && <CopyBtn text={topic.summary} />}
            </div>
          </div>

          <div>
            <div style={{ fontSize: 10, color: 'var(--ink-4)', marginBottom: 6, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>LONG-FORM ESSAY</div>
            <SimpleEditor value={topic.essay || ''} onChange={handleEssayChange} placeholder="Develop your thinking here…" />
          </div>
        </div>

        {/* RIGHT — book notes */}
        <div style={{ overflow: 'auto', padding: '18px 22px' }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 12 }}>
            <div style={SL}>Notes from books</div>
            <button onClick={() => setShowAttachPicker(p => !p)}
              style={{ fontSize: 11, padding: '4px 12px', borderRadius: 6, background: showAttachPicker ? 'var(--accent)' : 'transparent', color: showAttachPicker ? 'var(--paper-card)' : 'var(--ink-3)', border: '1px solid var(--paper-3)', cursor: 'pointer' }}>
              {showAttachPicker ? 'Done' : '+ attach note'}
            </button>
          </div>

          {showAttachPicker && (
            <div style={{ background: 'var(--paper-2)', border: '1px solid var(--paper-3)', borderRadius: 8, padding: '10px 12px', marginBottom: 12 }}>
              <input autoFocus value={attachSearch} onChange={e => setAttachSearch(e.target.value)}
                placeholder="Search your thoughts…"
                style={{ width: '100%', padding: '6px 10px', fontSize: 12, marginBottom: 8 }} />
              <div style={{ maxHeight: 200, overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: 5 }}>
                {unattached.slice(0, 15).map(t => {
                  const b = books.find(b => b.id === t.bookId);
                  return (
                    <div key={t.id} onClick={() => handleAttach(t.id)}
                      style={{ padding: '6px 10px', borderRadius: 6, cursor: 'pointer', background: 'var(--paper-card)', border: '1px solid var(--paper-3)', fontSize: 12, color: 'var(--ink)', lineHeight: 1.5 }}
                      onMouseEnter={e => e.currentTarget.style.borderColor = 'var(--accent-2)'}
                      onMouseLeave={e => e.currentTarget.style.borderColor = 'var(--paper-3)'}>
                      <span style={{ color: b?.color, fontSize: 10, fontStyle: 'italic', display: 'block', marginBottom: 2 }}>{b?.title}</span>
                      {t.text?.slice(0, 100)}{t.text?.length > 100 ? '…' : ''}
                    </div>
                  );
                })}
                {unattached.length === 0 && <div style={{ fontSize: 12, color: 'var(--ink-4)', fontStyle: 'italic' }}>No more thoughts to attach.</div>}
              </div>
            </div>
          )}

          {byBook.length === 0 ? (
            <div style={{ fontSize: 13, color: 'var(--ink-4)', fontStyle: 'italic' }}>No notes attached yet — use "+ attach note" above.</div>
          ) : (
            byBook.map(({ book, thoughts: bThoughts }) => (
              <div key={book?.id} style={{ marginBottom: 20 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 8 }}>
                  <div style={{ width: 7, height: 7, borderRadius: '50%', background: book?.color }} />
                  <span style={{ fontSize: 12, fontWeight: 500, color: 'var(--ink-2)', fontStyle: 'italic' }}>{book?.title}</span>
                  <span style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)' }}>{book?.author}</span>
                </div>
                {bThoughts.map(t => (
                  <MiniThoughtCard key={t.id} thought={t} book={book} thoughtTypes={thoughtTypes} onDetach={handleDetach} />
                ))}
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

const SL = { fontSize: 10, fontWeight: 500, color: 'var(--ink-4)', letterSpacing: '0.08em', textTransform: 'uppercase', marginBottom: 10, fontFamily: 'var(--font-mono)', fontStyle: 'normal', display: 'block' };
